style.css:
@-moz-document domain("play.pokemonshowdown.com") {
/* =====================================================
   DRAGON BALL ABRIDGED - FRIEZA THEME
   Purple / Black / White Tyrant UI
===================================================== */

/* ===== MAIN BACKGROUND ===== */

body {
    background:
        radial-gradient(circle at top,
        #5d2a91 0%,
        #1a0d2b 45%,
        #050507 100%) !important;

    color: #f6eaff !important;
    font-family: "Trebuchet MS", sans-serif !important;
}

/* ===== GLOBAL TEXT ===== */

a {
    color: #d9b3ff !important;
}

a:hover {
    color: #ffffff !important;
    text-shadow: 0 0 10px #c66cff !important;
}

/* ===== HEADER ===== */

.header,
.ps-roombar {
    background: rgba(8, 0, 20, 0.96) !important;
    border-bottom: 2px solid #c66cff !important;
    box-shadow: 0 0 20px #a020f0 !important;
}

/* ===== ROOM TABS ===== */

.roomtab {
    background: rgba(35, 10, 50, 0.8) !important;
    border-radius: 8px 8px 0 0 !important;
    transition: 0.2s ease !important;
}

.roomtab:hover,
.roomtab.cur {
    background:
        linear-gradient(
            90deg,
            #c66cff,
            #7d2ae8
        ) !important;

    color: white !important;
    box-shadow: 0 0 12px #d98cff !important;
}

/* ===== BUTTONS ===== */

.button,
select,
input,
textarea {
    background: #22092f !important;
    color: #ffffff !important;
    border: 1px solid #c66cff !important;
    border-radius: 12px !important;
    transition: all 0.25s ease !important;
}

.button:hover,
select:hover,
input:hover {
    background:
        linear-gradient(
            135deg,
            #c66cff,
            #7d2ae8
        ) !important;

    box-shadow: 0 0 16px #d98cff !important;
    transform: translateY(-2px);
}

/* ===== CHAT ===== */

.chat-log {
    background: rgba(12, 0, 20, 0.88) !important;
    border-left: 2px solid #c66cff !important;
}

.chat-log .username {
    color: #ffb6ff !important;
    font-weight: bold !important;
}

.message-log {
    color: #f6eaff !important;
}

/* ===== SIDEBAR ===== */

.ps-roomlist,
.userlist {
    background: rgba(15, 0, 25, 0.92) !important;
    border-right: 1px solid #c66cff !important;
}

/* ===== BATTLE WINDOW ===== */

.battle {
    background:
        radial-gradient(circle at center,
        rgba(90, 20, 140, 0.8),
        rgba(8, 0, 20, 1)) !important;

    border: 2px solid #d98cff !important;
    border-radius: 16px !important;
    box-shadow:
        0 0 25px rgba(198,108,255,0.7),
        inset 0 0 30px rgba(180,80,255,0.2) !important;
}

/* ===== TURN COUNTER ===== */

.turn {
    color: #ffffff !important;
    text-shadow: 0 0 10px #d98cff !important;
}

/* ===== POPUPS ===== */

.ps-popup,
.modal {
    background: rgba(18, 0, 28, 0.98) !important;
    border: 2px solid #c66cff !important;
    border-radius: 14px !important;
    color: #ffffff !important;
    box-shadow: 0 0 20px #a020f0 !important;
}

/* ===== TEAM BUILDER ===== */

.teamchart,
.teambar,
.folderpane {
    background: rgba(20, 0, 35, 0.94) !important;
    border: 1px solid #c66cff !important;
    border-radius: 12px !important;
}

/* ===== SCROLLBAR ===== */

::-webkit-scrollbar {
    width: 10px !important;
}

::-webkit-scrollbar-track {
    background: #120018 !important;
}

::-webkit-scrollbar-thumb {
    background:
        linear-gradient(
            #c66cff,
            #7d2ae8
        ) !important;

    border-radius: 10px !important;
}

/* ===== HP BARS ===== */

.hpbar {
    border-radius: 12px !important;
    overflow: hidden !important;
    box-shadow: 0 0 8px rgba(255,255,255,0.2) !important;
}

/* ===== GLASS EFFECT ===== */

.mainmenu,
.activitymenu,
.userlist,
.ps-popup {
    backdrop-filter: blur(10px);
}

/* ===== FRIEZA QUOTE LOADING STYLE ===== */

.mainmenu::before {
    content: "Oh my... this IS a rare opportunity.";
    display: block;
    text-align: center;
    color: #f5c3ff;
    font-size: 18px;
    font-weight: bold;
    margin-bottom: 10px;
    text-shadow: 0 0 10px #d98cff;
}

/* ===== SUBTLE ENERGY ANIMATION ===== */

.battle::after {
    content: "";
    position: absolute;
    inset: 0;
    pointer-events: none;

    background:
        radial-gradient(
            circle,
            rgba(220,120,255,0.08),
            transparent 70%
        );

    animation: friezaGlow 4s infinite alternate;
}

@keyframes friezaGlow {
    from {
        opacity: 0.4;
        transform: scale(1);
    }

    to {
        opacity: 0.9;
        transform: scale(1.03);
    }
}

/* ===== CLEANER PANELS ===== */

.ps-room,
.mainmenu,
.activitymenu {
    background: rgba(10, 0, 18, 0.78) !important;
    border: 1px solid rgba(198,108,255,0.35) !important;
    border-radius: 14px !important;
}

/* ===== REMOVE UGLY SHADOWS ===== */

* {
    text-shadow: none !important;
}

/* ===== SPECIAL TITLE GLOW ===== */

.logo {
    filter:
        drop-shadow(0 0 12px #c66cff)
        drop-shadow(0 0 20px #7d2ae8);
}
}
